    LANGUAGE_WRAPPER = "In a math contest, {m} clever monkeys divide a pile of bananas in order. For i = 1, 2, ..., {m}, the i-th monkey takes some bananas from the remaining pile, keeps the listed fraction of what it took, and divides the rest equally among the other {m_minus_1} monkeys. The keep fractions are {keep_fractions_str}. Every division yields a whole number of bananas at the moment it occurs. At the end, the monkeys' holdings are in the ratio {ratio_str}. Among all possibilities consistent with these rules, what is the least possible total number of bananas initially in the pile?"

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

